-- 033_cos_media_storage: add per-asset storage location and durable upload sessions.
-- Existing IDs, hashes and business references are preserved; no file movement.

-- @step media_storage
-- @replaces-check 003_media/create_media_asset
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_asset' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_asset')=21 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_asset' AND ((COLUMN_NAME='id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='auto_increment') OR (COLUMN_NAME='owner_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='uploaded_by' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='purpose' AND COLUMN_TYPE='varchar(32)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='media_kind' AND COLUMN_TYPE='varchar(16)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='original_name' AND COLUMN_TYPE='varchar(255)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='mime_type' AND COLUMN_TYPE='varchar(128)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='storage_key' AND COLUMN_TYPE='varchar(512)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='storage_provider' AND COLUMN_TYPE='varchar(16)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='local' AND EXTRA='') OR (COLUMN_NAME='cos_bucket' AND COLUMN_TYPE='varchar(255)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='cos_region' AND COLUMN_TYPE='varchar(64)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='cos_version_id' AND COLUMN_TYPE='varchar(255)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='etag' AND COLUMN_TYPE='varchar(255)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='crc64' AND COLUMN_TYPE='varchar(64)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='size_bytes' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='sha256' AND COLUMN_TYPE='char(64)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='status' AND COLUMN_TYPE='varchar(16)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='processing' AND EXTRA='') OR (COLUMN_NAME='duration_ms' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='probe_error' AND COLUMN_TYPE='varchar(512)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='created_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED') OR (COLUMN_NAME='updated_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)')))=21 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_asset')=5 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_asset' AND ((INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='id' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='uk_media_asset_storage_key' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='storage_key' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_asset_owner_purpose' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='owner_id' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_asset_owner_purpose' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=2 AND COLUMN_NAME='purpose' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_asset_status' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='status' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL)))=5 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='media_asset')=0 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `media_asset`
  ADD COLUMN `storage_provider` VARCHAR(16) NOT NULL DEFAULT 'local' AFTER `storage_key`,
  ADD COLUMN `cos_bucket` VARCHAR(255) NULL AFTER `storage_provider`,
  ADD COLUMN `cos_region` VARCHAR(64) NULL AFTER `cos_bucket`,
  ADD COLUMN `cos_version_id` VARCHAR(255) NULL AFTER `cos_region`,
  ADD COLUMN `etag` VARCHAR(255) NULL AFTER `cos_version_id`,
  ADD COLUMN `crc64` VARCHAR(64) NULL AFTER `etag`;

-- @step upload_session
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_upload_session' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_upload_session')=31 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_upload_session' AND ((COLUMN_NAME='id' AND COLUMN_TYPE='char(36)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (COLUMN_NAME='owner_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='uploaded_by' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='client_request_id' AND COLUMN_TYPE='char(36)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (COLUMN_NAME='request_digest' AND COLUMN_TYPE='char(64)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (COLUMN_NAME='purpose' AND COLUMN_TYPE='varchar(32)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='original_name' AND COLUMN_TYPE='varchar(255)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='mime_type' AND COLUMN_TYPE='varchar(128)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='size_bytes' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='fingerprint_sha256' AND COLUMN_TYPE='char(64)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (COLUMN_NAME='mode' AND COLUMN_TYPE='varchar(16)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='part_size' AND COLUMN_TYPE='int unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='parallel_limit' AND COLUMN_TYPE='tinyint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='3' AND EXTRA='') OR (COLUMN_NAME='staging_locator' AND COLUMN_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='upload_id' AND COLUMN_TYPE='varchar(255)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='state' AND COLUMN_TYPE='varchar(16)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='uploading' AND EXTRA='') OR (COLUMN_NAME='expires_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='last_credential_expires_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='claim_id' AND COLUMN_TYPE='char(36)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin') OR (COLUMN_NAME='lease_until' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='finalize_attempts' AND COLUMN_TYPE='tinyint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='0' AND EXTRA='') OR (COLUMN_NAME='candidate_objects' AND COLUMN_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='asset_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='receipt' AND COLUMN_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='receipt_expires_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='reason_code' AND COLUMN_TYPE='varchar(64)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='error_message' AND COLUMN_TYPE='varchar(512)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='finalized_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='cleaned_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='created_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED') OR (COLUMN_NAME='updated_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)')))=31 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_upload_session')=11 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='media_upload_session' AND ((INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='id' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='uk_media_upload_request' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='uploaded_by' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='uk_media_upload_request' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=2 AND COLUMN_NAME='client_request_id' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_queue' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='state' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_queue' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=2 AND COLUMN_NAME='lease_until' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_expiry' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='state' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_expiry' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=2 AND COLUMN_NAME='expires_at' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_credentials' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='state' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_credentials' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=2 AND COLUMN_NAME='last_credential_expires_at' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_receipt' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='state' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_media_upload_receipt' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=2 AND COLUMN_NAME='receipt_expires_at' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL)))=11 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='media_upload_session')=0 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `media_upload_session` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_id` BIGINT UNSIGNED NOT NULL,
  `uploaded_by` BIGINT UNSIGNED NOT NULL,
  `client_request_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_digest` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `purpose` VARCHAR(32) NOT NULL,
  `original_name` VARCHAR(255) NULL,
  `mime_type` VARCHAR(128) NOT NULL,
  `size_bytes` BIGINT UNSIGNED NOT NULL,
  `fingerprint_sha256` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `mode` VARCHAR(16) NOT NULL,
  `part_size` INT UNSIGNED NOT NULL,
  `parallel_limit` TINYINT UNSIGNED NOT NULL DEFAULT '3',
  `staging_locator` JSON NULL,
  `upload_id` VARCHAR(255) NULL,
  `state` VARCHAR(16) NOT NULL DEFAULT 'uploading',
  `expires_at` DATETIME(3) NOT NULL,
  `last_credential_expires_at` DATETIME(3) NULL,
  `claim_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `lease_until` DATETIME(3) NULL,
  `finalize_attempts` TINYINT UNSIGNED NOT NULL DEFAULT '0',
  `candidate_objects` JSON NULL,
  `asset_id` BIGINT UNSIGNED NULL,
  `receipt` JSON NULL,
  `receipt_expires_at` DATETIME(3) NULL,
  `reason_code` VARCHAR(64) NULL,
  `error_message` VARCHAR(512) NULL,
  `finalized_at` DATETIME(3) NULL,
  `cleaned_at` DATETIME(3) NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_media_upload_request` (`uploaded_by`, `client_request_id`),
  KEY `idx_media_upload_queue` (`state`, `lease_until`),
  KEY `idx_media_upload_expiry` (`state`, `expires_at`),
  KEY `idx_media_upload_credentials` (`state`, `last_credential_expires_at`),
  KEY `idx_media_upload_receipt` (`state`, `receipt_expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='持久媒体上传会话与请求墓碑';
